levels.usage:
// 二分边界的业务用法：
//   分页去重：按 id 找第一个 > lastId 的位置
//   区间统计：upperBound(x) - lowerBound(x) = x 的出现次数
//   版本回滚：找第一个 >= 目标版本的下标

stages.code:
function mergeSort(arr, cmp) {
  const c = cmp || ((a, b) => a - b)
  if (arr.length <= 1) return arr.slice()
  const mid = arr.length >> 1
  const left = mergeSort(arr.slice(0, mid), c)
  const right = mergeSort(arr.slice(mid), c)
  const out = []
  let i = 0
  let j = 0
  while (i < left.length && j < right.length) {
    if (c(right[j], left[i]) < 0) out.push(right[j++])
    else out.push(left[i++])
  }
  while (i < left.length) out.push(left[i++])
  while (j < right.length) out.push(right[j++])
  return out
}

function lowerBound(arr, target) {
  let lo = 0
  let hi = arr.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (arr[mid] < target) lo = mid + 1
    else hi = mid
  }
  return lo
}

function upperBound(arr, target) {
  let lo = 0
  let hi = arr.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (arr[mid] <= target) lo = mid + 1
    else hi = mid
  }
  return lo
}

stages.test:
{
  check('归并排序结果正确', () => {
    same(mergeSort([3, 1, 2, 5, 4]), [1, 2, 3, 4, 5])
    same(mergeSort([]), [])
  })
  check('归并排序是稳定的：相等元素保持原相对顺序', () => {
    const items = [{ k: 1, id: 'a' }, { k: 1, id: 'b' }, { k: 0, id: 'c' }]
    const sorted = mergeSort(items, (x, y) => x.k - y.k)
    same(sorted.map((x) => x.id), ['c', 'a', 'b'], '合并时相等取左侧才是稳定')
  })
  check('lowerBound 找第一个 >= target 的下标', () => {
    same(lowerBound([1, 2, 2, 3], 2), 1)
    same(lowerBound([1, 2, 2, 3], 4), 4)
  })
  check('upperBound 找第一个 > target 的下标', () => {
    same(upperBound([1, 2, 2, 3], 2), 3)
    same(upperBound([1, 2, 2, 3], 0), 0)
  })
  check('空数组 / 全大于 / 全小于的边界', () => {
    same(lowerBound([], 5), 0)
    same(upperBound([5, 6], 1), 0)
    same(lowerBound([5, 6], 9), 2)
  })
}

