function mergeSort(arr, cmp) {
  const c = cmp || ((a, b) => a - b)
  if (arr.length <= 1) return arr.slice()
  const mid = arr.length >> 1
  const left = mergeSort(arr.slice(0, mid), c)
  const right = mergeSort(arr.slice(mid), c)
  const out = []
  let i = 0
  let j = 0
  while (i < left.length && j < right.length) {
    if (c(right[j], left[i]) < 0) out.push(right[j++])
    else out.push(left[i++])
  }
  while (i < left.length) out.push(left[i++])
  while (j < right.length) out.push(right[j++])
  return out
}

function lowerBound(arr, target) {
  let lo = 0
  let hi = arr.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (arr[mid] < target) lo = mid + 1
    else hi = mid
  }
  return lo
}

function upperBound(arr, target) {
  let lo = 0
  let hi = arr.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (arr[mid] <= target) lo = mid + 1
    else hi = mid
  }
  return lo
}

function permute(nums) {
  const out = []
  const used = new Array(nums.length).fill(false)
  const path = []
  const dfs = () => {
    if (path.length === nums.length) { out.push(path.slice()); return }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue
      used[i] = true
      path.push(nums[i])
      dfs()
      path.pop()
      used[i] = false
    }
  }
  dfs()
  return out
}

function subsets(nums) {
  const out = []
  const dfs = (start, path) => {
    out.push(path.slice())
    for (let i = start; i < nums.length; i++) {
      path.push(nums[i])
      dfs(i + 1, path)
      path.pop()
    }
  }
  dfs(0, [])
  return out
}

function nQueens(n) {
  let count = 0
  const cols = new Set()
  const diag1 = new Set()
  const diag2 = new Set()
  const place = (row) => {
    if (row === n) { count++; return }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || diag1.has(row - c) || diag2.has(row + c)) continue
      cols.add(c); diag1.add(row - c); diag2.add(row + c)
      place(row + 1)
      cols.delete(c); diag1.delete(row - c); diag2.delete(row + c)
    }
  }
  place(0)
  return count
}

stages.test:
{
  check('全排列：n=3 得到 6 个排列且包含原序', () => {
    const out = permute([1, 2, 3])
    same(out.length, 6)
    ok(out.some((p) => p.join(',') === '1,2,3'))
    ok(out.every((p) => p.length === 3))
  })
  check('全排列的元素取自输入且不重复使用', () => {
    const out = permute(['a', 'b'])
    same(out.length, 2)
    same(out.slice().sort().join('|'), 'a,b|b,a')
  })
  check('子集：n=3 得到 8 个且包含空集与全集', () => {
    const out = subsets([1, 2, 3])
    same(out.length, 8)
    ok(out.some((s) => s.length === 0))
    ok(out.some((s) => s.join(',') === '1,2,3'))
  })
  check('N 皇后：4 皇后有 2 个解', () => {
    same(nQueens(4), 2)
  })
  check('N 皇后：8 皇后有 92 个解，1 皇后有 1 个解', () => {
    same(nQueens(8), 92)
    same(nQueens(1), 1)
  })
}

