function lis(nums) {
  if (!nums.length) return 0
  const dp = new Array(nums.length).fill(1)
  for (let i = 1; i < nums.length; i++) {
    for (let j = 0; j < i; j++) {
      if (nums[j] < nums[i]) dp[i] = Math.max(dp[i], dp[j] + 1)
    }
  }
  return Math.max.apply(null, dp)
}

function editDistance(a, b) {
  const m = a.length
  const n = b.length
  const dp = []
  for (let i = 0; i <= m; i++) dp.push(new Array(n + 1).fill(0))
  for (let i = 0; i <= m; i++) dp[i][0] = i
  for (let j = 0; j <= n; j++) dp[0][j] = j
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = a[i - 1] === b[j - 1]
        ? dp[i - 1][j - 1]
        : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    }
  }
  return dp[m][n]
}

function coinChange(coins, amount) {
  const dp = new Array(amount + 1).fill(Infinity)
  dp[0] = 0
  for (let i = 1; i <= amount; i++) {
    for (const c of coins) {
      if (i >= c && dp[i - c] + 1 < dp[i]) dp[i] = dp[i - c] + 1
    }
  }
  return dp[amount] === Infinity ? -1 : dp[amount]
}

stages.test:
{
  check('LIS：最长递增子序列长度', () => {
    same(lis([10, 9, 2, 5, 3, 7, 101, 18]), 4)
  })
  check('LIS：空数组与全递减', () => {
    same(lis([]), 0)
    same(lis([5, 4, 3]), 1)
  })
  check('编辑距离：horse → ros 是 3', () => {
    same(editDistance('horse', 'ros'), 3)
  })
  check('编辑距离：完全相同是 0，一边为空是另一边长度', () => {
    same(editDistance('abc', 'abc'), 0)
    same(editDistance('', 'abc'), 3)
  })
  check('零钱兑换：有解取最少，无解返回 -1', () => {
    same(coinChange([1, 2, 5], 11), 3)
    same(coinChange([2], 3), -1)
    same(coinChange([1], 0), 0)
  })
}

