// 面试答题模板（容量估算）：
//   1) 假设 DAU 与人均请求 → 平均 QPS
//   2) 峰值系数 2~5 → 峰值 QPS
//   3) 每条数据大小 × 写入量 × 保留期 × 副本 → 存储
//   4) 单机承载（通常 1k~5k QPS 视业务）→ 机器数
//   5) 留 30%~50% buffer，说明扩容方式

stages.code:
function estimateCapacity(p) {
  const avgReadQps = Math.ceil((p.dau * p.readsPerUserPerDay) / 86400)
  const avgWriteQps = Math.ceil((p.dau * p.writesPerUserPerDay) / 86400)
  const peakQps = Math.ceil(((p.dau * p.readsPerUserPerDay) / 86400 + (p.dau * p.writesPerUserPerDay) / 86400) * p.peakFactor)
  const bytes = p.dau * p.writesPerUserPerDay * p.writeBytes * p.retentionDays * p.replicas
  const storageGb = Math.ceil(bytes / (1024 * 1024 * 1024))
  const servers = Math.ceil(peakQps / p.qpsPerServer)
  return { avgReadQps, avgWriteQps, peakQps, storageGb, servers }
}

