    const r = estimateCapacity({
      dau: 1000000, readsPerUserPerDay: 10, writesPerUserPerDay: 1,
      peakFactor: 3, writeBytes: 1000, retentionDays: 365, replicas: 3, qpsPerServer: 2000
    })
    same(r.avgReadQps, 116, '1e6×10/86400=115.74 → 向上取整')
    same(r.avgWriteQps, 12)
    same(r.peakQps, 382, '峰值用未取整的平均值：(115.74+11.57)×3=381.9')
