levels.usage:
// 排查线上缓存问题的话术：
//   QPS 打满 + 大量空结果 → 穿透，看布隆过滤器是否漏配
//   某个热点 key 过期瞬间 RT 飙升 → 击穿，看是否用了 singleflight
//   整点大量 key 同时失效 → 雪崩，看 TTL 是否加了抖动

stages.code:
const GUARD_TABLE = {
  penetration: ['bloom-filter', 'null-cache', 'request-validate'],
  breakdown: ['singleflight', 'mutex-lock', 'hot-key-never-expire'],
  avalanche: ['ttl-jitter', 'multi-level-cache', 'circuit-breaker', 'warm-up']
}

function guardPlan(problem) {
  const plan = GUARD_TABLE[problem]
  if (!plan) throw new Error('未知的缓存问题: ' + problem)
  return plan.slice()
}

function addJitter(ttlMs, ratio, rand) {
  const factor = 1 - ratio + rand * ratio * 2
  return Math.round(ttlMs * factor)
}

stages.test:
{
  check('缓存穿透：布隆过滤器 + 空值缓存', () => {
    const plan = guardPlan('penetration')
    ok(plan.includes('bloom-filter'))
    ok(plan.includes('null-cache'))
  })
  check('缓存击穿：singleflight / 互斥锁', () => {
    const plan = guardPlan('breakdown')
    ok(plan.includes('singleflight'))
    ok(plan.includes('mutex-lock'))
  })
  check('缓存雪崩：TTL 抖动 + 多级缓存 + 熔断', () => {
    const plan = guardPlan('avalanche')
    ok(plan.includes('ttl-jitter'))
    ok(plan.includes('multi-level-cache'))
    ok(plan.includes('circuit-breaker'))
  })
  check('addJitter 在 [ttl×(1-ratio), ttl×(1+ratio)] 内抖动', () => {
    same(addJitter(1000, 0.2, 0), 800)
    same(addJitter(1000, 0.2, 0.5), 1000)
    same(addJitter(1000, 0.2, 0.999), 1200)
  })
  check('未知的缓存问题要抛错（不能静默返回空策略）', () => {
    throws(() => guardPlan('unknown'))
  })
}

