function createSnowflake(opts) {
  const workerId = opts.workerId
  const now = opts.now || (() => 0)
  let lastMs = -1
  let seq = 0

  return {
    next() {
      const ms = now()
      if (ms === lastMs) {
        seq = (seq + 1) & 0xfff
        if (seq === 0) {
          lastMs = ms + 1
          return { ms: lastMs, workerId, seq: 0, id: lastMs + '-' + workerId + '-0' }
        }
      } else {
