levels.usage:
// 秒杀链路：
//   网关令牌桶（允许突发）→ 请求入 MQ → 消费端漏桶（平滑下游）→ 库存扣减（幂等 + 唯一索引）
// 延迟队列的典型场景：
//   订单 30 分钟未支付自动取消、外卖超时提醒、重试退避

stages.code:
function createDeduper(windowMs) {
  const seen = new Map()

  return {
    accept(key, now) {
      const last = seen.get(key)
      if (last !== undefined && now - last < windowMs) return false
      seen.set(key, now)
      return true
    },
    size() { return seen.size }
  }
}

stages.test:
{
  check('首次出现的消息被接受，重复消息被拒绝', () => {
    const d = createDeduper(1000)
    same(d.accept('msg-1', 0), true)
    same(d.accept('msg-1', 10), false)
  })
  check('超过去重窗口后，同一条消息可以再次被接受', () => {
    const d = createDeduper(1000)
    same(d.accept('msg-1', 0), true)
    same(d.accept('msg-1', 999), false)
    same(d.accept('msg-1', 1000), true, '窗口边界按左闭右开处理')
  })
  check('不同业务键互不影响', () => {
    const d = createDeduper(1000)
    d.accept('order:1', 0)
    same(d.accept('order:2', 0), true)
    same(d.accept('order:1', 0), false)
  })
  check('size 反映当前记录数', () => {
    const d = createDeduper(1000)
    same(d.size(), 0)
    d.accept('a', 0)
    d.accept('b', 0)
    same(d.size(), 2)
  })
  check('同一 key 短时间内反复来，只放行第一次', () => {
    const d = createDeduper(500)
    let accepted = 0
    for (let i = 0; i < 5; i++) if (d.accept('pay:9001', 100 + i)) accepted++
    same(accepted, 1)
  })
}

