    const q = createDelayQueue()
    q.add('first', 50, 0)
    q.add('second', 50, 0)
    same(q.poll(50), ['first', 'second'])
  })
  check('没有消息时 poll 返回空数组', () => {
    const q = createDelayQueue()
    same(q.poll(1000), [])
  })
}

stages.code:
function createDeduper(windowMs) {
  const seen = new Map()

  return {
    accept(key, now) {
      const last = seen.get(key)
      if (last !== undefined && now - last < windowMs) return false
      seen.set(key, now)
      return true
    },
    size() { return seen.size }
  }
}

function createDelayQueue() {
  const items = []
  let seq = 0

  return {
    add(message, delayMs, now) {
      items.push({ message, due: now + delayMs, seq: seq++ })
    },
    poll(now) {
      const due = items
        .filter((item) => item.due <= now)
        .sort((a, b) => a.due - b.due || a.seq - b.seq)
      for (const item of due) {
        const idx = items.indexOf(item)
        if (idx >= 0) items.splice(idx, 1)
      }
      return due.map((item) => item.message)
    },
    size() { return items.length }
  }
}

function createTokenBucket(opts) {
  const capacity = opts.capacity
  const refillPerMs = opts.refillPerMs
  const now = opts.now
  let tokens = capacity
  let last = now()

  const refill = () => {
    const t = now()
    if (t > last) {
      tokens = Math.min(capacity, tokens + (t - last) * refillPerMs)
      last = t
    }
  }

  return {
    allow() {
      refill()
      if (tokens >= 1) {
        tokens -= 1
        return true
      }
      return false
    },
    available() {
      refill()
      return tokens
    }
  }
}

function createLeakyBucket(opts) {
  const capacity = opts.capacity
  const drainPerMs = opts.drainPerMs
  const now = opts.now
  let level = 0
  let last = now()

  const drain = () => {
    const t = now()
    if (t > last) {
      level = Math.max(0, level - (t - last) * drainPerMs)
      last = t
    }
  }

  return {
    offer() {
      drain()
      if (level + 1 > capacity) return false
      level += 1
      return true
    },
    level() {
      drain()
      return level
    }
  }
}

stages.test:
{
  check('令牌桶：容量内连续请求全部放行', () => {
    let t = 0
    const b = createTokenBucket({ capacity: 3, refillPerMs: 0.01, now: () => t })
    same([b.allow(), b.allow(), b.allow()], [true, true, true])
  })
  check('令牌桶：令牌耗尽后拒绝，时间流逝后恢复', () => {
    let t = 0
    const b = createTokenBucket({ capacity: 2, refillPerMs: 0.001, now: () => t })
    b.allow(); b.allow()
    same(b.allow(), false, '两个令牌都花完了')
    t = 1000
    same(b.allow(), true, '1 秒补 1 个令牌')
  })
  check('令牌桶：补充不会超过容量上限', () => {
    let t = 0
    const b = createTokenBucket({ capacity: 2, refillPerMs: 1, now: () => t })
    t = 100000
    same(b.available(), 2, '再久也只有 capacity 个')
  })
  check('漏桶：短时突发超过容量会被拒绝', () => {
    let t = 0
    const bucket = createLeakyBucket({ capacity: 2, drainPerMs: 0.001, now: () => t })
    same([bucket.offer(), bucket.offer(), bucket.offer()], [true, true, false])
  })
  check('漏桶：水位随时间匀速下降', () => {
    let t = 0
    const bucket = createLeakyBucket({ capacity: 10, drainPerMs: 0.01, now: () => t })
    bucket.offer(); bucket.offer(); bucket.offer()
    same(bucket.level(), 3)
    t = 200
    same(bucket.level(), 1, '200ms 排掉 2 个')
  })
}

