levels.tests:
{
  check('首次出现的消息被接受，重复消息被拒绝', () => {
    const d = createDeduper(1000)
    same(d.accept('msg-1', 0), true)
    same(d.accept('msg-1', 10), false)
  })
  check('超过去重窗口后，同一条消息可以再次被接受', () => {
    const d = createDeduper(1000)
    same(d.accept('msg-1', 0), true)
    same(d.accept('msg-1', 999), false)
    same(d.accept('msg-1', 1000), true, '窗口边界按左闭右开处理')
  })
  check('不同业务键互不影响', () => {
    const d = createDeduper(1000)
    d.accept('order:1', 0)
    same(d.accept('order:2', 0), true)
    same(d.accept('order:1', 0), false)
  })
  check('size 反映当前记录数', () => {
    const d = createDeduper(1000)
    same(d.size(), 0)
    d.accept('a', 0)
    d.accept('b', 0)
    same(d.size(), 2)
  })
  check('同一 key 短时间内反复来，只放行第一次', () => {
    const d = createDeduper(500)
    let accepted = 0
    for (let i = 0; i < 5; i++) if (d.accept('pay:9001', 100 + i)) accepted++
    same(accepted, 1)
  })
}
